/**
 ******************************************************************************
 * @file    mock_sd.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Configurable MSC_SdOps mock implementation.
 ******************************************************************************
 */
#include "mock_sd.h"

static int      s_state;
static uint32_t s_busy_polls_pending;
static int      s_fail_init;
static int      s_fail_wide_bus;
static int      s_fail_read;
static int      s_fail_write;
static int      s_fail_capacity;
static int      s_init_brings_up;
static uint32_t s_cap_block_num;
static uint16_t s_cap_block_size;

static uint32_t s_init_calls;
static uint32_t s_wide_bus_calls;
static uint32_t s_read_calls;
static uint32_t s_write_calls;
static uint32_t s_get_state_calls;
static uint32_t s_last_blk_addr;
static uint16_t s_last_blk_len;

void MockSd_Reset(void)
{
    s_state              = (int)MSC_CARD_NOT_READY;
    s_busy_polls_pending = 0U;
    s_fail_init          = 0;
    s_fail_wide_bus      = 0;
    s_fail_read          = 0;
    s_fail_write         = 0;
    s_fail_capacity      = 0;
    s_init_brings_up     = 1;
    s_cap_block_num      = 0x1D5A00U;   /* placeholder 3.9 GB card */
    s_cap_block_size     = 512U;

    s_init_calls      = 0U;
    s_wide_bus_calls  = 0U;
    s_read_calls      = 0U;
    s_write_calls     = 0U;
    s_get_state_calls = 0U;
    s_last_blk_addr   = 0U;
    s_last_blk_len    = 0U;
}

void MockSd_SetState(int state)                    { s_state = state; }
void MockSd_SetBusyPollsAfterIo(uint32_t polls)    { s_busy_polls_pending = polls; }
void MockSd_FailInit(int fail)                     { s_fail_init = fail; }
void MockSd_FailWideBus(int fail)                  { s_fail_wide_bus = fail; }
void MockSd_FailRead(int fail)                     { s_fail_read = fail; }
void MockSd_FailWrite(int fail)                    { s_fail_write = fail; }
void MockSd_FailCapacity(int fail)                 { s_fail_capacity = fail; }
void MockSd_InitBringsCardUp(int enable)           { s_init_brings_up = enable; }

void MockSd_SetCapacity(uint32_t block_num, uint16_t block_size)
{
    s_cap_block_num  = block_num;
    s_cap_block_size = block_size;
}

/* ---- MSC_SdOps callbacks ---- */

static int mock_get_state(void *ctx)
{
    (void)ctx;
    s_get_state_calls++;

    if (s_busy_polls_pending > 0U) {
        s_busy_polls_pending--;
        return (int)MSC_CARD_BUSY;
    }
    return s_state;
}

static int mock_card_init(void *ctx)
{
    (void)ctx;
    s_init_calls++;

    if (s_fail_init != 0) {
        return -1;
    }
    if (s_init_brings_up != 0) {
        s_state = (int)MSC_CARD_READY;
    }
    return 0;
}

static int mock_config_wide_bus(void *ctx)
{
    (void)ctx;
    s_wide_bus_calls++;
    return (s_fail_wide_bus != 0) ? -1 : 0;
}

static int mock_read_blocks(void *ctx, uint8_t *buf, uint32_t blk_addr,
                            uint16_t blk_len)
{
    (void)ctx;
    (void)buf;
    s_read_calls++;
    s_last_blk_addr = blk_addr;
    s_last_blk_len  = blk_len;
    return (s_fail_read != 0) ? -1 : 0;
}

static int mock_write_blocks(void *ctx, const uint8_t *buf, uint32_t blk_addr,
                             uint16_t blk_len)
{
    (void)ctx;
    (void)buf;
    s_write_calls++;
    s_last_blk_addr = blk_addr;
    s_last_blk_len  = blk_len;
    return (s_fail_write != 0) ? -1 : 0;
}

static int mock_get_capacity(void *ctx, uint32_t *block_num, uint16_t *block_size)
{
    (void)ctx;
    if (s_fail_capacity != 0) {
        return -1;
    }
    *block_num  = s_cap_block_num;
    *block_size = s_cap_block_size;
    return 0;
}

static const MSC_SdOps s_iface = {
    mock_get_state,
    mock_card_init,
    mock_config_wide_bus,
    mock_read_blocks,
    mock_write_blocks,
    mock_get_capacity,
    (void *)0,
};

const MSC_SdOps *MockSd_Iface(void) { return &s_iface; }

uint32_t MockSd_InitCalls(void)     { return s_init_calls; }
uint32_t MockSd_WideBusCalls(void)  { return s_wide_bus_calls; }
uint32_t MockSd_ReadCalls(void)     { return s_read_calls; }
uint32_t MockSd_WriteCalls(void)    { return s_write_calls; }
uint32_t MockSd_GetStateCalls(void) { return s_get_state_calls; }
uint32_t MockSd_LastBlkAddr(void)   { return s_last_blk_addr; }
uint16_t MockSd_LastBlkLen(void)    { return s_last_blk_len; }
